nd:#fff;text-align:left;cursor:pointer;color:#253329}.location-item:hover,.location-item.is-active{background:#f0f6f0}.location-pin{display:grid;place-items:center;flex:none;width:35px;height:35px;border-radius:9px;background:#e8f0ea;color:#1f5d3a;font-size:1.2rem}.location-copy{flex:1;min-width:0;display:flex;flex-direction:column;gap:.12rem}.location-copy strong{font-size:.9rem;overflow-wrap:anywhere}.location-copy small{font-size:.73rem;color:#68736b}.location-arrow{color:#9a7834}.map-empty{padding:2rem 1.2rem;text-align:center;color:#69746b}.map-empty>span{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:#e8f0ea;color:#1f5d3a;font-size:1.6rem;margin:0 auto 1rem}.map-empty strong{display:block;color:#26352a}.map-empty p{font-size:.85rem;margin:.4rem 0}.map-footnote{font-size:.78rem;color:#69746b;margin:1rem 0 0}.leaflet-popup-content-wrapper{border-radius:10px}.leaflet-popup-content{font-family:var(--sans);line-height:1.5}.leaflet-popup-content strong{display:block;font-size:.95rem;margin-bottom:.15rem}.leaflet-popup-content small{color:#68736b}.leaflet-popup-content a{display:inline-block;color:#1f5d3a;font-weight:700;margin-top:.35rem}@media(max-width:760px){.map-page{padding-top:1rem}.map-toolbar{flex-direction:column}.map-filter select{height:43px;width:100%}.map-layout{grid-template-columns:1fr;min-height:0}.map-canvas-wrap,#village-map{min-height:360px;height:360px}.map-sidebar{border-left:0;border-top:1px solid #e5e9e3}.location-list{max-height:320px}}
