<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin=""></script>
<script>
(() => {const el=document.getElementById('village-map');if(!el||!window.L)return;const items=[...document.querySelectorAll('.location-item')];const map=L.map(el,{scrollWheelZoom:false}).setView([-7.4,111.0],10);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);const markers=new Map();
items.forEach(b=>{const lat=Number(b.dataset.lat),lng=Number(b.dataset.lng);if(!Number.isFinite(lat)||!Number.isFinite(lng))return;const marker=L.marker([lat,lng]).addTo(map);const name=b.dataset.name,cat=b.dataset.category,desc=b.dataset.description,address=b.dataset.address;marker.bindPopup('<strong>'+esc(name)+'</strong><small>'+esc(cat)+'</small>'+(desc?'<p>'+esc(desc)+'</p>':'')+(address?'<small>'+esc(address)+'</small>':'')+'<br><a target="_blank" rel="noopener" href="https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(lat+','+lng)+'">Petunjuk arah ↗</a>');markers.set(b.dataset.id,marker);b.addEventListener('click',()=>focus(b,marker));});function esc(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}function focus(b,m){items.forEach(x=>x.classList.toggle('is-active',x===b));map.flyTo(m.getLatLng(),Math.max(map.getZoom(),15),{duration:.6});m.openPopup()}
const valid=[...markers.values()];if(valid.length){map.fitBounds(L.featureGroup(valid).getBounds().pad(.16),{maxZoom:14});}else{map.setView([-7.4,111.0],10)}
const search=document.getElementById('location-search'),category=document.getElementById('location-category'),count=document.getElementById('location-count');function filter(){const q=search.value.trim().toLowerCase(),c=category.value;let n=0;items.forEach(b=>{const ok=(!q||(b.dataset.name+' '+b.dataset.category+' '+b.dataset.address).toLowerCase().includes(q))&&(!c||b.dataset.category===c);b.hidden=!ok;const m=markers.get(b.dataset.id);if(m){if(ok){if(!map.hasLayer(m))m.addTo(map);n++}else map.removeLayer(m)}});count.textContent=n;}search.addEventListener('input',filter);category.addEventListener('change',filter);})();
</script>
@endpush